import{_ as h,o as i,c as t,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Vì sao Assessment không đồng nghĩa với Learning","description":"","frontmatter":{},"headers":[],"relativePath":"learning/assessment-khac-learning.md","filePath":"learning/assessment-khac-learning.md"}'),g={name:"learning/assessment-khac-learning.md"};function e(c,n,o,r,s,u){return i(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="vi-sao-assessment-khong-đong-nghia-voi-learning" tabindex="-1">Vì sao Assessment không đồng nghĩa với Learning <a class="header-anchor" href="#vi-sao-assessment-khong-đong-nghia-voi-learning" aria-label="Permalink to &quot;Vì sao Assessment không đồng nghĩa với Learning&quot;">​</a></h1><p>Trên trang này# Vì sao Assessment không đồng nghĩa với Learning <a href="#vi-sao-assessment-khong-đong-nghia-voi-learning">​</a> Hai việc này dùng chung một hình thức — learner ngồi trả lời câu hỏi — nên rất dễ bị coi là một. Nhưng chúng có mục tiêu ngược nhau, và trộn lẫn chúng làm hỏng cả hai.</p><h2 id="muc-tieu-nguoc-nhau-​" tabindex="-1">Mục tiêu ngược nhau <a href="#muc-tieu-nguoc-nhau">​</a> <a class="header-anchor" href="#muc-tieu-nguoc-nhau-​" aria-label="Permalink to &quot;Mục tiêu ngược nhau [​](#muc-tieu-nguoc-nhau)&quot;">​</a></h2><p>Learning ExperienceMuốn learner thành công. Có gợi ý, có bài mẫu, có thể thử lại. Sai là một phần của quá trình. Thành công đo bằng: con có giỏi lên không? Assessment ExperienceMuốn biết sự thật. Không gợi ý, không nhắc, không cứu. Sai là dữ liệu quý. Thành công đo bằng: hệ thống có hiểu con rõ hơn không? Một Learning Experience mà learner sai hết là một Learning Experience thất bại — bài quá khó, scaffold không đủ. Một Assessment Experience mà learner sai hết lại có thể <strong>hoàn toàn thành công</strong>: nó vừa xác định chính xác một lỗ hổng mà không ai biết.</p><h2 id="đieu-gi-hong-khi-tron-hai-thu-​" tabindex="-1">Điều gì hỏng khi trộn hai thứ <a href="#đieu-gi-hong-khi-tron-hai-thu">​</a> <a class="header-anchor" href="#đieu-gi-hong-khi-tron-hai-thu-​" aria-label="Permalink to &quot;Điều gì hỏng khi trộn hai thứ [​](#đieu-gi-hong-khi-tron-hai-thu)&quot;">​</a></h2><p><strong>Khi bài đo cũng cố dạy.</strong> Hiện lời giải ngay sau mỗi câu, gợi ý khi learner ngập ngừng — nghe tử tế, nhưng nó phá huỷ dữ liệu. Câu số 7 giờ đây bị ảnh hưởng bởi lời giải của câu số 6, và hệ thống không còn biết learner biết gì từ trước và học được gì trong lúc làm bài. Kết luận thu được không dùng để lập kế hoạch cho những tuần sau nữa. <strong>Khi việc học bị chấm điểm.</strong> Đây là chiều nguy hiểm hơn. Nếu mọi lần luyện tập đều được tính vào một con số, learner học được bài học sai: <em>đừng thử thứ mình chưa chắc</em>. Đứa trẻ tối ưu điểm sẽ chọn bài dễ, tránh dạng lạ, và không bao giờ đến gần vùng thật sự dạy được nó điều mới. Cách chắc chắn nhất để giết tinh thần thử nghiệm của một đứa trẻ là chấm điểm mọi lần nó thử. Cái giá thực tế Một học sinh luyện đề ba tháng, điểm thi thử tăng đều, rồi thi thật kém hẳn. Chuyện này xảy ra khi <em>toàn bộ</em> thời gian là assessment. Đề thi thử không dạy gì cả; điểm tăng vì em ấy quen dạng đề, không phải vì hiểu sâu hơn. Đến khi đề thật đổi cách hỏi, phần chưa từng được xây lộ ra.</p><h2 id="nemo12-phan-tach-chung-nhu-the-nao-​" tabindex="-1">Nemo12 phân tách chúng như thế nào <a href="#nemo12-phan-tach-chung-nhu-the-nao">​</a> <a class="header-anchor" href="#nemo12-phan-tach-chung-nhu-the-nao-​" aria-label="Permalink to &quot;Nemo12 phân tách chúng như thế nào [​](#nemo12-phan-tach-chung-nhu-the-nao)&quot;">​</a></h2><p>Trong phòng lab, mỗi hoạt động đều mang nhãn rõ ràng để learner <strong>biết mình đang ở chế độ nào</strong>:</p><ul><li>🧪 <strong>Khám phá</strong> và ✏️ <strong>Luyện tập</strong> — để học. Sai thoải mái. Có gợi ý.</li><li>🎯 <strong>Đo mức vững</strong> — để đo. Không gợi ý. Kết quả hiện ở cuối. Việc nói rõ ràng này không phải chi tiết giao diện. Một đứa trẻ không biết mình đang bị đo sẽ căng thẳng ở chỗ không cần căng, và thả lỏng ở chỗ cần nghiêm túc. Biết rõ luật chơi là điều kiện để chơi thật. Có một khác biệt nhỏ nhưng cố ý giữa hai chế độ: khi luyện tập, kết quả hiện <strong>ngay sau mỗi câu</strong> — vì phản hồi tức thì giúp học. Khi đo mức vững, kết quả <strong>giấu tới cuối bài</strong> — vì biết mình vừa sai sẽ đổi cách làm câu tiếp theo và làm nhiễu phép đo.</li></ul><h2 id="ty-le-giua-hai-loai-khong-co-đinh-​" tabindex="-1">Tỷ lệ giữa hai loại không cố định <a href="#ty-le-giua-hai-loai-khong-co-đinh">​</a> <a class="header-anchor" href="#ty-le-giua-hai-loai-khong-co-đinh-​" aria-label="Permalink to &quot;Tỷ lệ giữa hai loại không cố định [​](#ty-le-giua-hai-loai-khong-co-đinh)&quot;">​</a></h2><p>Learner còn cách kỳ thi 8 tháng sẽ dành phần lớn thời gian cho Learning Experience. Learner còn 12 ngày sẽ nghiêng hẳn sang retrieval và đo — vì lúc đó câu hỏi quan trọng nhất không còn là &quot;học thêm được gì&quot; mà là &quot;còn chỗ nào chưa chắc mà kịp sửa&quot;. Tỷ lệ này được tính từ mục tiêu và thời gian còn lại, không phải một con số cài sẵn trong hệ thống. <a href="/decisions/hoc-test-nghi">Xem cách hệ thống quyết định →</a> Learning giúp learner tiến lên. Assessment giúp hệ thống nhìn rõ. Cần cả hai, nhưng đừng bao giờ nhầm cái này thành cái kia.</p>',11)])])}const k=h(g,[["render",e]]);export{m as __pageData,k as default};
